/* ===================== JAW MOTION & TMJ IMPLANTS LAB =====================
   Tabs: TMJ anatomy & the two phases of opening · tracking jaw motion (imaging + markers, rigid-body pose) · mandible as a lever
   (bite force and joint reaction) · TMJ implants and the growing jaw · the two-phase design project · drills.
   Representative values from the clinical/biomechanics literature (normal opening ≥ 40 mm, rotation phase ≈ first 20–25 mm, condylar
   condylar-center path ≈ 18 mm forward and 4 mm down, eminence inclination ≈ 30–45°, adult molar bite force ≈ 300–800 N, children ≈ 150–400 N). Written for ME 320;
   the project tab follows the phased plan with the pediatric head and neck surgery partner (kept anonymous on the page) (Theia for the donor leg, chairside tracker + EMG + bite force in clinic, optical capture with a dental clutch for the jaw); no patient data.                     */
const TJ=(()=>{
  const $=(s)=>document.querySelector(s); const f=(x,d=1)=>isFinite(x)?(+x).toFixed(d):"—"; const R=(d)=>d*Math.PI/180; const D=(r)=>r*180/Math.PI;
  let svgN=0; const svg=(w,h,inner,cls="")=>{ const uid="j"+(svgN++); return `<svg viewBox="0 0 ${w} ${h}" class="mlsvg ${cls}" preserveAspectRatio="xMidYMid meet">${inner.split("@@").join(uid)}</svg>`; };
  const MK={"#7cff6b":"ahg","#22d3ee":"ahc","#ffd23f":"ahy","#ff8a3d":"aho","#ff5a5a":"ahr","#b58cff":"ahp"};
  const ARROW=`<defs>${Object.entries(MK).map(([c,id])=>`<marker id="${id}@@" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="${c}"/></marker>`).join("")}</defs>`;
  const arrow=(x1,y1,x2,y2,col,w=3)=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" marker-end="url(#${MK[col]||"ahc"}@@)"/>`;
  const txt=(x,y,s,o="")=>`<text x="${x}" y="${y}" class="mlab" ${o}>${s}</text>`;
  const seg=(label,opts,cur,attr)=>`<div class="seg"><span class="seglab">${label}</span>${opts.map(([v,t])=>`<button type="button" class="segbtn ${v===cur?"on":""}" ${attr}="${v}">${t}</button>`).join("")}</div>`;
  const playBtn=(id,on)=>`<button type="button" class="btn small play ${on?"on":""}" id="${id}" title="play / pause">${on?"❚❚ Pause":"▶ Play"}</button>`;
  const animator=(getState,setValue,draw,min,max,speed)=>{ let raf=null,dir=1,last=0; const step=(t)=>{ const S=getState(); if(!S.play){ raf=null; return; } const dt=last?(t-last)/1000:0; last=t; let v=S.val+dir*speed*dt; if(v>max){ v=max; dir=-1; } if(v<min){ v=min; dir=1; } setValue(v); draw(); raf=requestAnimationFrame(step); }; return {start(){ if(!raf){ last=0; raf=requestAnimationFrame(step); } },stop(){ if(raf) cancelAnimationFrame(raf); raf=null; }}; };

  /* ---------- sagittal mandible model (mm, skull frame: x anterior, y superior, origin at the closed-mouth condyle center) ----------
     Opening is rotation about the condyle for the first `rotLim` mm of interincisal distance, then the condyle also translates down the
     articular eminence (slope `slope`) while rotation continues. Incisor point I sits ~`Lc` mm from the condyle (adult ≈ 90 mm).            */
  const JAW={Lc:90,rotLim:22,slope:14,transMax:18,maxOpen:48}; /* condylar-center path ≈ 18 mm forward, 4 mm down at full opening (Naeije 2002; Walck et al.) */
  function jawPose(open,J=JAW){ /* interincisal opening (mm) → {theta (deg), trans (mm along eminence), condyle, incisor, icr} */
    const o=Math.min(open,J.maxOpen); const r=J.Lc; const th1=Math.min(o,J.rotLim)/r; /* rad: rotation-only phase, arc ≈ chord */
    const extra=Math.max(0,o-J.rotLim); const t=J.transMax*Math.min(1,extra/(J.maxOpen-J.rotLim)); /* translation grows with the second phase */
    const th=th1+0.7*extra/r; /* beyond the hinge phase the extra opening is shared between continued rotation and the condylar slide */
    const C=[t*Math.cos(R(J.slope)),-t*Math.sin(R(J.slope))]; /* condyle: anterior and inferior along the eminence */
    const a0=R(-12); /* closed-mouth angle of the condyle→incisor line below the horizontal */
    const I=[C[0]+r*Math.cos(a0-th),C[1]+r*Math.sin(a0-th)]; const I0=[r*Math.cos(a0),r*Math.sin(a0)];
    const gap=Math.hypot(I[0]-I0[0],I[1]-I0[1]);
    return {theta:D(th),trans:t,C,I,I0,gap,phase:o<=J.rotLim?"rotation (hinge) phase":"rotation + translation (gliding) phase"}; }
  const MAND=(r)=>[[0,0],[-7,-10],[-6,-36],[0,-54],[r*0.45,-60],[r*0.88,-48],[r*1.02,-30],[r,-18],[r*0.9,-19],[r*0.6,-21],[r*0.3,-22],[r*0.2,-18],[r*0.15,-4],[r*0.1,-9],[6,-4]]; /* mandible outline in its own frame (closed): condyle, ramus, angle, body, chin, alveolar ridge, coronoid, notch */
  let an={open:12,play:false,showICR:true,showDisc:true,envelope:false};
  const anim=animator(()=>({play:an.play,val:an.open}),(v)=>{ an.open=v; },()=>renderAnat(),0,JAW.maxOpen,22);
  function renderAnat(){ const el=$("#anat"); const P=jawPose(an.open); const sc=2.7; const ox=190, oy=90; const X=(x)=>ox+x*sc, Y=(y)=>oy-y*sc;
    const emin=`<path d="M${X(-18)} ${Y(8)} Q ${X(-10)} ${Y(13)} ${X(0)} ${Y(12)} Q ${X(8)} ${Y(11)} ${X(12)} ${Y(5)} L ${X(24)} ${Y(-5)} L ${X(34)} ${Y(-8)}" fill="none" stroke="#e8e2d2" stroke-width="5" stroke-linecap="round"/>`;
    const fossa=txt(X(-30),Y(20),"glenoid fossa",'style="fill:#c9d7ff;font-size:11px"')+txt(X(16),Y(1),"articular eminence",'style="fill:#c9d7ff;font-size:11px"');
    const C=P.C; const a=R(-12)-R(P.theta);
    const ramus=(()=>{ const r=JAW.Lc; const pts=MAND(r);
      const rot=([x,y])=>{ const c=Math.cos(-R(P.theta)),s=Math.sin(-R(P.theta)); return [C[0]+x*c-y*s,C[1]+x*s+y*c]; };
      const q=pts.map(rot).map(([x,y])=>`${X(x)},${Y(y)}`).join(" "); return `<polygon points="${q}" fill="#e8e2d2" fill-opacity=".85" stroke="#fff" stroke-width="1"/>`; })();
    const cond=`<circle cx="${X(C[0])}" cy="${Y(C[1])}" r="${7*sc/3.2}" fill="#f6f1e4" stroke="#fff"/>`;
    const disc=an.showDisc?`<path d="M${X(C[0]-9)} ${Y(C[1]+8)} Q ${X(C[0]+1)} ${Y(C[1]+13)} ${X(C[0]+10)} ${Y(C[1]+6)}" fill="none" stroke="#22d3ee" stroke-width="4" stroke-linecap="round"/>${txt(X(C[0]+13),Y(C[1]+12),"disc",'style="fill:#22d3ee;font-size:11px"')}`:"";
    const skullTeeth=`<rect x="${X(46)}" y="${Y(-14)}" width="${46*sc}" height="${4*sc}" fill="#f6f1e4" stroke="#fff"/>${txt(X(48),Y(-11),"maxillary teeth (fixed)",'style="fill:#c9d7ff;font-size:10px"')}`;
    const inc=`<circle cx="${X(P.I[0])}" cy="${Y(P.I[1])}" r="4" fill="#ffd23f"/>${txt(X(P.I[0])+8,Y(P.I[1])+5,`opening ${f(P.gap)} mm`,'style="fill:#ffd23f;font-size:12px"')}`;
    const icr=an.showICR?`<circle cx="${X(C[0])}" cy="${Y(C[1])}" r="3" fill="#ff5a5a"/>${P.trans>0.3?arrow(X(0),Y(0),X(C[0]),Y(C[1]),"#ff5a5a",2):""}${txt(X(C[0])-110,Y(C[1])+28,`condyle slide ${f(P.trans)} mm`,'style="fill:#ff5a5a;font-size:11px"')}`:"";
    const env=an.envelope?(()=>{ const pts=[]; for(let o=0;o<=JAW.maxOpen;o+=2){ const p=jawPose(o); pts.push(`${X(p.I[0])},${Y(p.I[1])}`); } const back=[]; for(let o=JAW.maxOpen;o>=0;o-=4){ const p=jawPose(o); back.push(`${X(p.I[0]-6-o*0.12)},${Y(p.I[1]+1)}`); } return `<polyline points="${pts.join(" ")}" fill="none" stroke="#b58cff" stroke-width="2" stroke-dasharray="5 4"/><polyline points="${back.join(" ")}" fill="none" stroke="#b58cff" stroke-width="1.5" stroke-dasharray="2 4"/>${txt(X(JAW.Lc-30),Y(-70),"Posselt-type envelope: incisor path (sagittal)",'style="fill:#b58cff;font-size:11px"')}`; })():"";
    const dial=`<g transform="translate(${X(C[0])},${Y(C[1])})"><path d="M${22*Math.cos(R(-12))} ${-22*Math.sin(R(-12))} A 22 22 0 0 1 ${22*Math.cos(a)} ${-22*Math.sin(a)}" fill="none" stroke="#7cff6b" stroke-width="2"/></g>${txt(X(C[0])-62,Y(C[1])+62,`θ = ${f(P.theta)}°`,'style="fill:#7cff6b;font-size:12px"')}`;
    el.innerHTML=`<div class="two"><div>${svg(560,330,ARROW+env+emin+fossa+skullTeeth+ramus+cond+disc+dial+icr+inc)}</div>
      <div><h4>Two joints, two phases</h4><p>The temporomandibular joint is a <b>ginglymoarthrodial</b> joint: a hinge (ginglymus) and a sliding joint (arthrodia) stacked in one capsule, separated by a fibrocartilage <b>disc</b>. Both TMJs are linked by the mandible, so they always move together (a bicondylar joint).</p>
      <p><b>Phase 1 — rotation.</b> For roughly the first 20–25 mm of interincisal opening the condyle spins in the glenoid fossa under the disc (lower joint space). The instantaneous center of rotation is near the condyle center.</p>
      <p><b>Phase 2 — translation.</b> To open wider, the condyle–disc complex slides forward out of the fossa and down the articular eminence (upper joint space). The eminence itself is steep (≈ 30–45° to the Frankfort plane), but the path of the condyle's center is shallow: about 18 mm forward and 4 mm down at full opening. Rotation continues at the same time, so the instantaneous axis migrates. Normal maximum opening is ≈ 40–55 mm; less than 40 mm in an adult is restricted. (The implant study on this page places the switch between the phases at 22° of jaw rotation, with MMO at 32°.)</p>
      <p class="note">Current state: <b>${P.phase}</b>. Lateral excursion (≈ 8–12 mm each side) and protrusion (≈ 8–10 mm) are the other two clinical motions; the Posselt envelope is the border path of the incisor point in the sagittal plane.</p>
      <label class="note">Opening <b id="jopenv">${f(an.open)} mm</b><input type="range" id="jopen" min="0" max="${JAW.maxOpen}" step="0.5" value="${an.open}"></label>
      <div class="playrow">${playBtn("jplay",an.play)}<label class="chk"><input type="checkbox" id="jicr" ${an.showICR?"checked":""}> condyle path</label><label class="chk"><input type="checkbox" id="jdisc" ${an.showDisc?"checked":""}> disc</label><label class="chk"><input type="checkbox" id="jenv" ${an.envelope?"checked":""}> incisor envelope</label></div>
      <table class="mini"><tr><th>Quantity</th><th>Value</th></tr><tr><td>Rotation θ</td><td>${f(P.theta)}°</td></tr><tr><td>Condylar translation</td><td>${f(P.trans)} mm along its path (${f(P.trans*Math.cos(R(JAW.slope)))} mm anterior, ${f(P.trans*Math.sin(R(JAW.slope)))} mm inferior)</td></tr><tr><td>Interincisal opening</td><td>${f(P.gap)} mm</td></tr><tr><td>Model</td><td>condyle→incisor ${JAW.Lc} mm · rotation-only to ${JAW.rotLim} mm · condylar path ${JAW.slope}° below horizontal</td></tr></table></div></div>`;
    $("#jopen").oninput=(e)=>{ an.open=+e.target.value; renderAnat(); };
    $("#jplay").onclick=()=>{ an.play=!an.play; if(an.play) anim.start(); else anim.stop(); renderAnat(); };
    $("#jicr").onchange=(e)=>{ an.showICR=e.target.checked; renderAnat(); }; $("#jdisc").onchange=(e)=>{ an.showDisc=e.target.checked; renderAnat(); }; $("#jenv").onchange=(e)=>{ an.envelope=e.target.checked; renderAnat(); };
    fixSubs(el); }

  /* ---------- 2. tracking jaw motion: imaging + markers, rigid-body pose ---------- */
  const METHODS=[
    ["CT / CBCT","Bone geometry: condyle, fossa, eminence, dentition. Sub-millimeter voxels; CBCT uses a lower dose than medical CT.","Static only; ionising radiation (a real constraint for children); soft tissue and the disc are poorly seen."],
    ["MRI","The disc, capsule, muscles and marrow; no ionising radiation. Cine or 'dynamic' MRI can capture slow opening sequences.","Lower spatial resolution than CT for bone; long scans; motion must be slow and repeated for cine sequences."],
    ["Optical motion capture","Markers on a tooth-borne splint (mandible) and a headband or glasses (skull); 100–500 Hz; full 6-DOF path of any mandibular point once the splint is registered to the CT.","Line of sight; marker cluster must be rigid with the bone (skin markers slide 2–5 mm over the jaw); needs a calibrated multi-camera volume."],
    ["Electromagnetic / ultrasonic jaw trackers","Small sensor on the lower incisors, receiver on the head; portable, used chairside.","Metal in the room distorts EM fields; usually tracks one point (incisor) plus orientation."],
    ["Video / depth camera (markerless)","No hardware on the patient; attractive for children.","Tracks the skin, not the bone; accuracy of a few millimeters; occlusion by lips."]];
  let tr={theta:14,tx:6,ty:-4,noise:0,skin:0};
  const MARK=[[22,-26],[58,-30],[38,-48]]; /* splint markers in the mandible frame (mm), condyle at origin when closed */
  const kabsch2=(P,Q)=>{ /* least-squares rigid fit P→Q in 2-D: returns {theta,t} */ const n=P.length; const cp=[0,0],cq=[0,0]; P.forEach((p,i)=>{ cp[0]+=p[0]/n; cp[1]+=p[1]/n; cq[0]+=Q[i][0]/n; cq[1]+=Q[i][1]/n; });
    let sxx=0,sxy=0,syx=0,syy=0; P.forEach((p,i)=>{ const a=[p[0]-cp[0],p[1]-cp[1]], b=[Q[i][0]-cq[0],Q[i][1]-cq[1]]; sxx+=a[0]*b[0]; sxy+=a[0]*b[1]; syx+=a[1]*b[0]; syy+=a[1]*b[1]; });
    const th=Math.atan2(sxy-syx,sxx+syy); const c=Math.cos(th),s=Math.sin(th); return {theta:D(th),t:[cq[0]-(c*cp[0]-s*cp[1]),cq[1]-(s*cp[0]+c*cp[1])]}; };
  function renderTrack(){ const el=$("#track"); const c=Math.cos(R(-tr.theta)),s=Math.sin(R(-tr.theta)); /* opening = clockwise in the sagittal view (x anterior, y up) */
    const rnd=()=>(Math.random()*2-1)*tr.noise; const Q=MARK.map(([x,y],i)=>[tr.tx+c*x-s*y+rnd()+(i===2?tr.skin:0),tr.ty+s*x+c*y+rnd()+(i===2?-tr.skin*0.6:0)]);
    const fit=kabsch2(MARK,Q); const Cfit=fit.t; const Ctrue=[tr.tx,tr.ty]; const errC=Math.hypot(Cfit[0]-Ctrue[0],Cfit[1]-Ctrue[1]);
    const sc=4.6, ox=70, oy=50; const X=(x)=>ox+x*sc, Y=(y)=>oy-y*sc;
    const dots=(M,col,lab)=>M.map(([x,y],i)=>`<circle cx="${X(x)}" cy="${Y(y)}" r="5" fill="${col}"/>${txt(X(x)+7,Y(y)-6,lab+(i+1),`style="fill:${col};font-size:11px"`)}`).join("");
    const tri=(M,col)=>`<polygon points="${M.map(([x,y])=>`${X(x)},${Y(y)}`).join(" ")}" fill="none" stroke="${col}" stroke-width="1.5" stroke-dasharray="4 3"/>`;
    const g=svg(560,340,ARROW+`<line x1="${X(-12)}" y1="${Y(0)}" x2="${X(92)}" y2="${Y(0)}" stroke="#2c4274"/><line x1="${X(0)}" y1="${Y(6)}" x2="${X(0)}" y2="${Y(-40)}" stroke="#2c4274"/>${txt(X(80),Y(0)-6,"x (anterior)",'style="fill:#c9d7ff;font-size:11px"')}${txt(X(0)+6,Y(4),"y (superior)",'style="fill:#c9d7ff;font-size:11px"')}`+tri(MARK,"#9fd8ff")+dots(MARK,"#9fd8ff","P")+tri(Q,"#ffd23f")+dots(Q,"#ffd23f","P'")+`<circle cx="${X(0)}" cy="${Y(0)}" r="4" fill="#ff5a5a"/>${txt(X(0)-62,Y(0)+18,"condyle (closed)",'style="fill:#ff5a5a;font-size:11px"')}<circle cx="${X(Cfit[0])}" cy="${Y(Cfit[1])}" r="4" fill="none" stroke="#7cff6b" stroke-width="2"/>${txt(X(Cfit[0])+8,Y(Cfit[1])+16,"condyle from the fit",'style="fill:#7cff6b;font-size:11px"')}`);
    el.innerHTML=`<div class="two"><div>${g}<p class="note">Three splint markers in the skull frame before (blue) and after (yellow) a movement. The least-squares rigid-body fit (Kabsch / SVD) recovers the rotation and the translation of the condyle — the same method the gait lab uses for a thigh marker cluster.</p></div>
      <div><h4>From markers to joint kinematics</h4><p>A rigid body in the plane has 3 degrees of freedom (6 in 3-D). With ≥ 2 markers (≥ 3 non-collinear in 3-D) you can solve for the pose that best maps the marker cluster from one frame to another, then carry <i>any</i> point of the bone — the condyle center from the CT — along with it. That is how a motion-capture trial becomes a condylar path.</p>
      <label class="note">True rotation θ <b>${f(tr.theta)}°</b><input type="range" id="trth" min="0" max="30" step="0.5" value="${tr.theta}"></label>
      <label class="note">True condyle slide, anterior <b>${f(tr.tx)} mm</b><input type="range" id="trtx" min="0" max="14" step="0.5" value="${tr.tx}"></label>
      <label class="note">True condyle slide, inferior <b>${f(-tr.ty)} mm</b><input type="range" id="trty" min="-10" max="0" step="0.5" value="${tr.ty}"></label>
      <label class="note">Marker noise (± mm) <b>${f(tr.noise)} mm</b><input type="range" id="trn" min="0" max="2" step="0.1" value="${tr.noise}"></label>
      <label class="note">Skin-marker artifact on P3 (mm) <b>${f(tr.skin)} mm</b><input type="range" id="trs" min="0" max="8" step="0.5" value="${tr.skin}"></label>
      <table class="mini"><tr><th></th><th>True</th><th>Recovered</th></tr><tr><td>θ</td><td>${f(tr.theta)}°</td><td>${f(-fit.theta)}°</td></tr><tr><td>Condyle (x, y)</td><td>(${f(tr.tx)}, ${f(tr.ty)}) mm</td><td>(${f(Cfit[0])}, ${f(Cfit[1])}) mm</td></tr><tr><td>Condyle position error</td><td colspan="2"><b>${f(errC,2)} mm</b></td></tr></table>
      <p class="note">Noise averages out across markers; a marker that moves with the skin instead of the bone does not — it biases the whole fit. Hence tooth-borne splints for the mandible and a tight headband or glasses frame for the skull.</p>
      <button type="button" class="btn small" id="trre">Re-sample noise</button></div></div>
      <h4 style="margin-top:14px">Ways to see and track the jaw</h4><table class="mini txt"><tr><th>Method</th><th>What it gives</th><th>Limits</th></tr>${METHODS.map(m=>`<tr><td><b>${m[0]}</b></td><td>${m[1]}</td><td>${m[2]}</td></tr>`).join("")}</table>
      <p class="note">A full kinematic model combines them: CT/CBCT for the bone surfaces and joint centers, MRI for the disc and soft tissue, and marker tracking for the motion. Everything is expressed in a skull frame (e.g. the Frankfort horizontal through the orbitale and porion points) and a mandible frame built from the two condylion points and the menton, following ISB-style conventions.</p>`;
    $("#trth").oninput=(e)=>{ tr.theta=+e.target.value; renderTrack(); }; $("#trtx").oninput=(e)=>{ tr.tx=+e.target.value; renderTrack(); }; $("#trty").oninput=(e)=>{ tr.ty=+e.target.value; renderTrack(); };
    $("#trn").oninput=(e)=>{ tr.noise=+e.target.value; renderTrack(); }; $("#trs").oninput=(e)=>{ tr.skin=+e.target.value; renderTrack(); }; $("#trre").onclick=renderTrack; fixSubs(el); }

  /* ---------- 3. mandible as a lever: bite force and joint reaction ---------- */
  const BITE={inc:{n:"Incisors",b:85},pre:{n:"Premolars",b:60},mol:{n:"First molar",b:45}}; /* bite point distance anterior to the condyle (mm) */
  let lv={Fm:400,Ft:250,bite:"mol"};
  const LEV={am:30,at:12,phiT:70}; /* masseter+medial pterygoid resultant 30 mm anterior of the condyle, near-vertical; temporalis 12 mm anterior, pulling up and back at 70° to the horizontal */
  function lever(v){ const b=BITE[v.bite].b; const Tx=-v.Ft*Math.cos(R(LEV.phiT)), Ty=v.Ft*Math.sin(R(LEV.phiT)); /* temporalis: posterior (−x) and superior */
    const Fb=(v.Fm*LEV.am+Ty*LEV.at)/b; /* moments about the condyle: muscles (ccw, +) = bite (cw) */
    const Ry=Fb-v.Fm-Ty, Rx=-Tx; /* ΣF = 0 on the mandible: R is the force of the skull on the condyle */
    return {b,Tx,Ty,Fb,Rx,Ry,Rmag:Math.hypot(Rx,Ry),ratio:Math.hypot(Rx,Ry)/Fb}; }
  function renderLever(){ const el=$("#lever"); const r=lever(lv); const sc=3.0, ox=90, oy=70; const X=(x)=>ox+x*sc, Y=(y)=>oy-y*sc; const kN=(F)=>F/7;
    const body=`<polygon points="${MAND(100).map(([x,y])=>`${X(x)},${Y(y)}`).join(" ")}" fill="#e8e2d2" fill-opacity=".9" stroke="#fff"/><circle cx="${X(0)}" cy="${Y(0)}" r="7" fill="#f6f1e4" stroke="#fff"/>`;
    const Fm=arrow(X(LEV.am),Y(-30),X(LEV.am),Y(-30)-kN(lv.Fm),"#ff8a3d")+txt(X(LEV.am)+6,Y(-30)-kN(lv.Fm)-4,`Fm = ${lv.Fm} N (masseter + medial pterygoid)`,'style="fill:#ff8a3d;font-size:11px"');
    const Ft=arrow(X(LEV.at),Y(-8),X(LEV.at)+kN(lv.Ft)*Math.cos(R(180-LEV.phiT)),Y(-8)-kN(lv.Ft)*Math.sin(R(LEV.phiT)),"#ffd23f")+txt(X(LEV.at)-10,Y(-8)-kN(lv.Ft)*Math.sin(R(LEV.phiT))-8,`Ft = ${lv.Ft} N (temporalis, ${LEV.phiT}°)`,'style="fill:#ffd23f;font-size:11px"');
    const Fb=arrow(X(r.b),Y(-18)-kN(r.Fb)-6,X(r.b),Y(-18)-6,"#7cff6b")+txt(X(r.b)-30,Y(-66),`bite Fb = ${f(r.Fb,0)} N on the ${BITE[lv.bite].n.toLowerCase()}`,'style="fill:#7cff6b;font-size:11px"');
    const Rr=arrow(X(0)-kN(r.Rx),Y(0)+kN(r.Ry),X(0),Y(0),"#ff5a5a")+txt(X(0)-70,Y(0)+kN(-r.Ry)+16,`joint reaction R = ${f(r.Rmag,0)} N`,'style="fill:#ff5a5a;font-size:11px"');
    el.innerHTML=`<div class="two"><div>${svg(560,300,ARROW+`<line x1="${X(0)}" y1="${Y(0)}" x2="${X(110)}" y2="${Y(0)}" stroke="#2c4274" stroke-dasharray="4 4"/>`+body+Fm+Ft+Fb+Rr)}<p class="note">Free-body diagram of the mandible in the sagittal plane (one side shown; forces are totals for both sides). The jaw is a <b>class III lever</b>: the fulcrum (TMJ) is at one end, the muscle effort acts between the fulcrum and the load (the bite).</p></div>
      <div><h4>Set the muscles and the bite point</h4>
      <label class="note">Masseter + medial pterygoid F_m <b>${lv.Fm} N</b><input type="range" id="lvfm" min="100" max="900" step="10" value="${lv.Fm}"></label>
      <label class="note">Temporalis F_t <b>${lv.Ft} N</b><input type="range" id="lvft" min="0" max="600" step="10" value="${lv.Ft}"></label>
      ${seg("Bite point",Object.entries(BITE).map(([k,v])=>[k,`${v.n} (${v.b} mm)`]),lv.bite,"data-bite")}
      <table class="mini"><tr><th>Equilibrium</th><th>Result</th></tr><tr><td>ΣM<sub>condyle</sub> = 0</td><td>F_b = (F_m·${LEV.am} + F_t sin${LEV.phiT}°·${LEV.at}) / ${r.b} = <b>${f(r.Fb,0)} N</b></td></tr><tr><td>ΣF_x = 0</td><td>R_x = ${f(r.Rx,0)} N (anterior)</td></tr><tr><td>ΣF_y = 0</td><td>R_y = ${f(r.Ry,0)} N (${r.Ry<0?"skull pushes down on the condyle":"skull pulls up — not possible, the joint would unload"})</td></tr><tr><td>|R| / F_b</td><td><b>${f(r.ratio,2)}</b></td></tr></table>
      <p class="note">Move the bite forward (incisors) and the same muscle effort gives a smaller bite force but a <i>larger</i> joint load — the lever arm ratio works against you. Adult maximal molar bite forces are typically 300–800 N; children aged 6–12 produce roughly 150–400 N, and bite force rises with age, muscle cross-section and dental development. Implant designers use these loads, multiplied by the number of chewing cycles a day (on the order of a thousand or more), to set strength and fatigue targets.</p></div></div>`;
    $("#lvfm").oninput=(e)=>{ lv.Fm=+e.target.value; renderLever(); }; $("#lvft").oninput=(e)=>{ lv.Ft=+e.target.value; renderLever(); }; el.querySelectorAll("[data-bite]").forEach(b=>b.onclick=()=>{ lv.bite=b.dataset.bite; renderLever(); }); fixSubs(el); }

  /* ---------- 4. implants and the growing jaw ---------- */
  let im={d:6,e:8,F:300,Se:500,cyc:1500,view:"recon"};
  function stem(v){ const A=Math.PI*v.d*v.d/4, I=Math.PI*Math.pow(v.d,4)/64; const M=v.F*v.e; const sb=M*(v.d/2)/I, sa=v.F/A; const s=sb+sa; return {A,I,M,sb,sa,s,fos:v.Se/s,peryear:v.cyc*365}; }
  function renderImpl(){ const el=$("#impl"); const r=stem(im);
    const pic=svg(420,300,`<path d="M40 60 Q 120 20 210 60 L 230 70 Q 150 110 60 90 Z" fill="#9fd8ff" fill-opacity=".9" stroke="#fff"/><text x="240" y="40" class="mlab" style="fill:#9fd8ff;font-size:11px">fossa component</text><text x="240" y="54" class="mlab" style="fill:#9fd8ff;font-size:11px">(UHMWPE on a metal backing)</text>
      <circle cx="140" cy="100" r="22" fill="#cfcfd6" stroke="#fff"/><text x="170" y="98" class="mlab" style="fill:#c9d7ff;font-size:11px">condylar head (CoCr alloy)</text>
      <path d="M128 118 L 118 150 L 112 250 L 96 258 L 96 268 L 150 268 L 150 258 L 136 250 L 150 150 L 152 118 Z" fill="#dcdce4" stroke="#fff"/><text x="160" y="190" class="mlab" style="fill:#c9d7ff;font-size:11px">ramus plate / stem (Ti alloy),</text><text x="160" y="204" class="mlab" style="fill:#c9d7ff;font-size:11px">fixed to the ramus with screws</text>
      ${[170,200,230].map(y=>`<circle cx="124" cy="${y}" r="4" fill="#ffd23f"/>`).join("")}<text x="20" y="290" class="mlab" style="fill:#c9d7ff;font-size:10px">schematic of a total TMJ replacement (not a specific device)</text>`);
    const tabs=seg("Topic",[["recon","Mandible reconstruction"],["tjr","Total joint replacement"],["ped","The growing jaw"],["mat","Materials, wear & fatigue"]],im.view,"data-iv");
    const body=im.view==="recon"?`<p>In a child, the usual reason to rebuild the jaw is a <b>tumour of the mandible</b> — an ameloblastoma or a desmoid tumour, for example — removed with a segment of bone. The defect is bridged with a <b>fibula free flap</b>: a length of the patient's own fibula, with its blood vessels, cut into pieces and fixed with a titanium <b>reconstruction plate and screws</b>, then re-attached to the neck vessels. The surgeons plan the cuts on the CT with virtual surgical planning and 3-D-printed cutting guides, so the engineering starts before the operation.</p>
      <p><b>Two surgical sites, two sets of mechanics.</b> The new jaw must carry bite loads through plates and screws while the bone unites and, in a child, keep growing; the donor leg has lost its fibula, which matters for the ankle (the lateral malleolus is kept, but the shaft is gone) and for gait — altered walking has been reported in about half of children after a fibula harvest for jaw reconstruction. A full outcome study therefore tracks the jaw and the leg.</p>
      <p><b>What the engineer measures.</b> Opening, lateral excursion and protrusion; the condylar path when a condyle is preserved; chewing-side preference; muscle activity (EMG of masseter and temporalis) and bite force on each side; and, for the leg, walking symmetry and ankle function. Repeated over 3, 6 and 12 months and then yearly, these numbers show whether function returns and whether the reconstruction keeps pace with growth — things a CT cannot show without more radiation.</p>
      <p class="note">The plate check in the <i>Materials, wear &amp; fatigue</i> topic and problem 8 treat the reconstruction plate as a beam loaded by the bite moment at the defect; screw pull-out limits what a thin pediatric cortex can hold.</p>`
      :im.view==="tjr"?`<p>An alloplastic <b>total TMJ replacement</b> has two parts: a <b>fossa component</b> (an ultra-high-molecular-weight polyethylene bearing surface, usually on a metal backing fixed to the zygomatic arch) and a <b>condylar / ramus component</b> (a cobalt–chromium head on a titanium-alloy plate screwed to the lateral ramus). It restores the hinge; the sliding phase is largely lost, so maximal opening after replacement is typically smaller than in a healthy joint, and lateral excursion toward the opposite side is reduced because the lateral pterygoid no longer pulls on a native condyle.</p>
      <p><b>Stock vs patient-specific.</b> Stock systems come in a few sizes and are shaped to fit at surgery; patient-specific systems are designed on the patient's CT (often from a 3-D-printed skull model) so the plate matches the ramus and the fossa matches the arch — the reason imaging and a reliable motion record come first in any design project.</p>
      <p><b>Common indications.</b> Ankylosis (bony fusion of the joint), end-stage degenerative or inflammatory joint disease, condylar resorption, loss of the condyle after tumour resection or trauma, and failed previous surgery. The engineering goals are a stable, pain-free hinge; adequate opening for eating, speech and dental care; and a device that survives decades of chewing cycles.</p>`
      :im.view==="ped"?`<p>Children are not small adults here. The <b>condylar cartilage is a growth site</b>: the mandible lengthens from the condyle through adolescence, and the ramus height, chin position and dental occlusion all depend on it. An implanted joint does not grow, so an alloplastic joint in a young child would be outgrown — most total-joint systems are intended for skeletally mature patients, with pediatric use reserved for selected cases (for example recurrent ankylosis after failed grafts) and planned revisions.</p>
      <p><b>Reconstruction options that can grow.</b> A <b>costochondral graft</b> (a piece of rib with its cartilage cap) is the classic autogenous reconstruction of a child's condyle because the cartilage cap can keep growing — but its growth is unpredictable (too little, or sometimes too much). <b>Distraction osteogenesis</b> lengthens the mandible slowly (about 1 mm/day) by pulling apart a surgical cut with an external or internal device while new bone forms in the gap; it is the mainstay for mandibular hypoplasia in conditions such as hemifacial microsomia and Pierre Robin sequence.</p>
      <p><b>Why motion tracking matters for children.</b> Growth, surgery and ankylosis change the joint over time, so serial measurements of opening, deviation on opening, lateral excursion and condylar translation document function with no radiation at all — something CT cannot do repeatedly in a child. A tracked kinematic record also tells a designer what motion a future device or graft must allow, and gives a baseline to judge outcomes against.</p>`
      :`<p><b>Bearing couple.</b> Metal (CoCr) on UHMWPE is the standard orthopaedic couple. Wear debris from polyethylene drives inflammation and bone loss (osteolysis) around hip implants, so wear rate — Archard's law, V = k·F·s — sets the service life. The TMJ is helped by low sliding distances per cycle (a few millimeters in the hinge phase) and loads far below those in the hip.</p>
      <p><b>Fatigue.</b> Chewing applies on the order of a thousand or more load cycles a day — roughly half a million to a million a year — so the condylar stem must stay below the material's fatigue (endurance) strength, not just its yield strength, at the stress concentrations around screw holes and the neck of the head. Titanium alloys have a usable endurance limit (≈ 500 MPa for polished Ti-6Al-4V in rotating bending, much lower with notches or corrosion); the design check below is the bending-plus-axial stress at the stem.</p>
      <div class="two"><div><label class="note">Stem diameter d <b>${im.d} mm</b><input type="range" id="imd" min="4" max="10" step="0.5" value="${im.d}"></label><label class="note">Load offset e (head center to stem axis) <b>${im.e} mm</b><input type="range" id="ime" min="2" max="16" step="0.5" value="${im.e}"></label><label class="note">Joint load F <b>${im.F} N</b><input type="range" id="imf" min="50" max="800" step="10" value="${im.F}"></label><label class="note">Endurance strength S_e <b>${im.Se} MPa</b><input type="range" id="imse" min="150" max="600" step="10" value="${im.Se}"></label><label class="note">Chewing cycles per day <b>${im.cyc}</b><input type="range" id="imc" min="500" max="3000" step="100" value="${im.cyc}"></label></div>
      <div><table class="mini"><tr><th>Stem check</th><th></th></tr><tr><td>Bending moment M = F·e</td><td>${f(r.M/1000,2)} N·m</td></tr><tr><td>σ_bend = 32M/(πd³)</td><td>${f(r.sb,0)} MPa</td></tr><tr><td>σ_axial = 4F/(πd²)</td><td>${f(r.sa,1)} MPa</td></tr><tr><td>σ_max</td><td><b>${f(r.s,0)} MPa</b></td></tr><tr><td>Fatigue factor of safety S_e/σ_max</td><td><b style="color:${r.fos>=2?"#7cff6b":r.fos>=1?"#ffd23f":"#ff5a5a"}">${f(r.fos,2)}</b></td></tr><tr><td>Load cycles per year</td><td>${(r.peryear/1e3).toFixed(0)} × 10³ (10 years ≈ ${(r.peryear*10/1e6).toFixed(1)} million)</td></tr></table><p class="note">A notch factor of 2–3 at a screw hole would divide the allowable stress accordingly; this is why real stems are much stouter than the minimum that static strength suggests.</p></div></div>`;
    el.innerHTML=`<div class="two"><div>${pic}</div><div>${tabs}${body}</div></div>`;
    el.querySelectorAll("[data-iv]").forEach(b=>b.onclick=()=>{ im.view=b.dataset.iv; renderImpl(); });
    ["imd","ime","imf","imse","imc"].forEach(id=>{ const e=$("#"+id); if(e) e.oninput=(ev)=>{ im[{imd:"d",ime:"e",imf:"F",imse:"Se",imc:"cyc"}[id]]=+ev.target.value; renderImpl(); }; }); fixSubs(el); }


  /* ---------- 5. the implant comparison study (Walck, Lim & Rosenstein) on the real skull ---------- */
  let sj={system:"healthy",angle:12,play:false,showMuscles:false,showLines:true}; let sjWrap=null;
  const sjAnim=animator(()=>({play:sj.play,val:sj.angle}),(v)=>{ sj.angle=Math.min(v,JAW3D.SYS[sj.system].max); },()=>{ JAW3D.set({angle:sj.angle}); sjReadout(); },0,32,10);
  function chart(id,series,ymax,ylab,unit){ const W=560,H=230,L=58,Rm=16,Tp=14,B=34; const X=(a)=>L+(W-L-Rm)*a/32, Y=(v)=>Tp+(H-Tp-B)*(1-v/ymax);
    const grid=[0,0.25,0.5,0.75,1].map(f=>`<line x1="${L}" y1="${Y(f*ymax)}" x2="${W-Rm}" y2="${Y(f*ymax)}" stroke="#2c4274" stroke-dasharray="3 4"/><text x="${L-6}" y="${Y(f*ymax)+4}" text-anchor="end" class="mlab" style="font-size:10px;fill:#c9d7ff">${(f*ymax).toLocaleString()}</text>`).join("");
    const xs=[0,10,20,22,32].map(a=>`<line x1="${X(a)}" y1="${Tp}" x2="${X(a)}" y2="${H-B}" stroke="${a===22?"#ff8a3d":"#2c4274"}" stroke-dasharray="${a===22?"5 3":"3 4"}"/><text x="${X(a)}" y="${H-B+14}" text-anchor="middle" class="mlab" style="font-size:10px;fill:#c9d7ff">${a}°</text>`).join("");
    const lines=series.map(sr=>{ const pts=sr.v.map((v,i)=>v==null?null:`${X(i)},${Y(v)}`).filter(Boolean); return `<polyline points="${pts.join(" ")}" fill="none" stroke="${sr.col}" stroke-width="${sr.k===sj.system?3.5:1.8}" opacity="${sr.k===sj.system?1:0.55}"/>`; }).join("");
    const cur=series.find(sr=>sr.k===sj.system); const a=Math.round(Math.min(sj.angle,JAW3D.SYS[sj.system].max)); const cv=cur&&cur.v[a]; const mark=cv==null?"":`<circle cx="${X(a)}" cy="${Y(cv)}" r="5" fill="${cur.col}" stroke="#fff"/><text x="${X(a)+8}" y="${Y(cv)-6}" class="mlab" style="font-size:11px;fill:${cur.col}">${cv.toLocaleString()} ${unit}</text>`;
    const leg=series.map((sr,i)=>`<rect x="${L+i*120}" y="${H-10}" width="14" height="3" fill="${sr.col}"/><text x="${L+i*120+18}" y="${H-6}" class="mlab" style="font-size:10px;fill:#c9d7ff">${sr.n}</text>`).join("");
    return svg(W,H,`${grid}${xs}<text x="${L}" y="${Tp-4}" class="mlab" style="font-size:10px;fill:#c9d7ff">${ylab}</text><text x="${X(22)+3}" y="${Tp+10}" class="mlab" style="font-size:10px;fill:#ff8a3d">translation phase →</text>${lines}${mark}${leg}`); }
  const SCOL={healthy:"#7cff6b",ps:"#ffd23f",generic:"#22d3ee",fff:"#ff5a5a"};
  function sjReadout(){ const el=$("#sjread"); if(!el) return; const r=JAW3D.readout(); if(!r) return; const a=Math.round(r.angle); const D=JAWDATA.disp; const study=sj.system==="healthy"?D.healthy[a]:sj.system==="ps"?D.ps[a]:D.generic[Math.min(a,22)]; const Tq=JAWDATA.torque[sj.system][a];
    el.innerHTML=`<tr><td>Jaw rotation</td><td>${a}° of ${r.max}° (${sj.system==="healthy"||sj.system==="ps"?"MMO = 32°":"rotation-only limit = 22°"})</td></tr><tr><td>Condyle translation</td><td>${r.slide.toFixed(1)} mm along the fossa path</td></tr><tr><td>Incisor displacement on this skull</td><td>${r.disp.toFixed(1)} mm (inferior ${r.inferior.toFixed(1)} mm)</td></tr><tr><td>Study value (NIH mandible)</td><td>${study!=null?study.toFixed(1)+" mm":"—"}</td></tr><tr><td>Net closing torque about the ICR</td><td>${Tq!=null?Tq.toLocaleString()+" N·mm":"—"}</td></tr>`;
    const c1=$("#sjchart1"), c2=$("#sjchart2"); if(c1) c1.innerHTML=chart("t",[{k:"healthy",n:"Healthy",col:SCOL.healthy,v:JAWDATA.torque.healthy},{k:"ps",n:"Patient-specific",col:SCOL.ps,v:JAWDATA.torque.ps},{k:"generic",n:"Generic",col:SCOL.generic,v:JAWDATA.torque.generic},{k:"fff",n:"Free fibula flap",col:SCOL.fff,v:JAWDATA.torque.fff}],30000,"net torque about the ICR (N·mm)","N·mm");
    if(c2) c2.innerHTML=chart("d",[{k:"healthy",n:"Healthy",col:SCOL.healthy,v:JAWDATA.disp.healthy},{k:"ps",n:"Patient-specific",col:SCOL.ps,v:JAWDATA.disp.ps},{k:"generic",n:"Generic / FFF",col:SCOL.generic,v:JAWDATA.disp.generic},{k:"fff",n:"",col:SCOL.fff,v:JAWDATA.disp.generic}],40,"inferior displacement of the incisors (mm)","mm");
    const sl=$("#sjang"); if(sl&&document.activeElement!==sl) sl.value=sj.angle; const sv=$("#sjangv"); if(sv) sv.textContent=f(sj.angle,0)+"°"; }
  function renderStudy(){ const el=$("#study"); const S=JAW3D.SYS;
    el.innerHTML=`<p>The jaw-closing motion of a healthy TMJ has two phases: <b>pure rotation</b> of the condyle about its instantaneous center of rotation (ICR) from mouth closed to 22° of jaw rotation, then <b>rotation plus translation</b> of the condyle forward and down the mandibular fossa up to the maximum mouth-open position (MMO, 32°). A reconstruction decides which of these the patient keeps. In this study the healthy jaw was compared with a <b>free fibula flap</b> reconstruction and two implants — a <b>generic</b> metal-and-polymer joint that behaves as a revolute (pin) joint, and a <b>patient-specific</b> joint that behaves as a pin-in-a-slot and can translate — using CAD models built on an NIH mandible (male, 50–65 y) and the muscle lines of action of the jaw closers. Here the same kinematics drive the real skull; the lines of action are the study's coordinates.</p>
      ${seg("System",Object.keys(S).map(k=>[k,S[k].n]),sj.system,"data-sys")}
      <div class="two"><div><div class="scene3d-slot"></div>
        <label class="note">Jaw rotation <b id="sjangv">${f(sj.angle,0)}°</b><input type="range" id="sjang" min="0" max="32" step="0.5" value="${sj.angle}"></label>
        <div class="playrow">${playBtn("sjplay",sj.play)}<label class="chk"><input type="checkbox" id="sjmus" ${sj.showMuscles?"checked":""}> muscles</label><label class="chk"><input type="checkbox" id="sjlines" ${sj.showLines?"checked":""}> lines of action &amp; forces</label></div>
        <table class="mini txt" id="sjread"></table></div>
      <div><div id="sjchart1"></div><div id="sjchart2"></div></div></div>
      <h4 style="margin-top:12px">What each system keeps</h4><table class="mini txt"><tr><th>System</th><th>Joint analogy</th><th>Max rotation</th><th>Condyle translation</th><th>Muscles cut</th><th>Peak net torque</th><th>Incisor drop at MMO</th></tr>
      <tr><td>Healthy jaw</td><td>rotation + slide along the fossa</td><td>32°</td><td>18.3 mm anterior, 3.9 mm inferior</td><td>none</td><td>26 300 N·mm</td><td>34.8 mm</td></tr>
      <tr><td>Patient-specific implant</td><td>pin-in-slot</td><td>32°</td><td>16.9 mm (7.65 % shorter path)</td><td>deep masseter, lateral pterygoid; 20 % of superficial masseter</td><td>18 600 N·mm (−29.3 %)</td><td>34.4 mm (−1.15 %)</td></tr>
      <tr><td>Generic implant</td><td>revolute (pin)</td><td>22°</td><td>none</td><td>deep masseter, lateral pterygoid; 20 % of superficial masseter</td><td>13 000 N·mm; nothing beyond 22°</td><td>22.5 mm (−35.3 %)</td></tr>
      <tr><td>Free fibula flap</td><td>revolute, no closers</td><td>22°</td><td>none</td><td>ramus and all of temporalis, masseter, pterygoids</td><td>0</td><td>22.5 mm (−35.3 %)</td></tr></table>
      <h4 style="margin-top:12px">How the numbers were made</h4><p><b>Kinematics.</b> The mandible is a link of length ℓ<sub>m</sub> (100.2 mm, adult male) from the ICR to the incisors; the ICR follows a best-fit polynomial path along the fossa (healthy: R² = 0.997; PS implant: 0.996) scaled to the mean condylar excursion. Each position closes a three-bar loop ℓ<sub>m</sub>e<sup>jΦ₁</sup> + ℓ<sub>b</sub>e<sup>jΦ₂</sup> + ℓ<sub>g</sub>e<sup>jΦ₃</sup> = 0 — two sliders and a revolute during the translation phase, two revolutes and a slider during pure rotation — the same vector-loop method as the Multi-Joint lab. Inferior displacement was then measured directly on the incisor point at one-degree steps.</p>
      <p><b>Kinetics.</b> Net torque about the ICR = Σ (muscle force × perpendicular distance from the ICR to its line of action), with the eight closing muscles projected onto the sagittal plane and maximum forces from the literature. The lateral pterygoids insert at the origin and contribute no moment. Cutting muscles (table above) removes their terms; the generic implant's torque stops at 22° because it cannot rotate further; the FFF has no closers left on that side, so its torque is zero.</p>
      <p><b>Reading the charts.</b> During pure rotation every system that keeps the temporalis and medial pterygoid produces similar torque; the difference opens up in the translation phase, where the healthy jaw and the PS implant keep rotating (and the moment arms grow) while the pin joints have stopped. That is the engineering case for an implant that translates: it is not the strength of the hinge, it is the degrees of freedom.</p>
      <p><b>Limits the authors note.</b> Sagittal plane only; the healthy contralateral side was ignored; the condylar path for the PS implant does not reach as far inferiorly as the real fossa; lateral deviation, protrusion and retrusion were not modeled — all of which the motion-tracking phases of the design project would supply.</p>
      <p class="note">${JAWDATA.credit}</p>`;
    const slot=el.querySelector(".scene3d-slot"); if(!sjWrap){ sjWrap=document.createElement("div"); sjWrap.className="scene3d"; sjWrap.style.cssText="user-select:none;position:relative;height:360px;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:radial-gradient(ellipse at 50% 40%,#101a33,#070b16 70%)"; sjWrap.innerHTML='<canvas id="sjcanvas" style="width:100%;height:100%;display:block;touch-action:none"></canvas>'; slot.replaceWith(sjWrap); JAW3D.mount("#sjcanvas"); JAW3D.onReady(()=>{ JAW3D.set({system:sj.system,angle:sj.angle,showMuscles:sj.showMuscles,showLines:sj.showLines}); sjReadout(); }); } else slot.replaceWith(sjWrap);
    JAW3D.set({system:sj.system,angle:Math.min(sj.angle,S[sj.system].max),showMuscles:sj.showMuscles,showLines:sj.showLines}); sjReadout();
    el.querySelectorAll("[data-sys]").forEach(b=>b.onclick=()=>{ sj.system=b.dataset.sys; sj.angle=Math.min(sj.angle,S[sj.system].max); renderStudy(); });
    $("#sjang").oninput=(e)=>{ sj.angle=Math.min(+e.target.value,S[sj.system].max); sjAnim.stop(); JAW3D.set({angle:sj.angle}); sjReadout(); };
    $("#sjplay").onclick=()=>{ sj.play=!sj.play; if(sj.play) sjAnim.start(); else sjAnim.stop(); $("#sjplay").textContent=sj.play?"❚❚ Pause":"▶ Play"; $("#sjplay").classList.toggle("on",sj.play); };
    $("#sjmus").onchange=(e)=>{ sj.showMuscles=e.target.checked; JAW3D.set({showMuscles:sj.showMuscles}); }; $("#sjlines").onchange=(e)=>{ sj.showLines=e.target.checked; JAW3D.set({showLines:sj.showLines}); };
    fixSubs(el); }
  /* ---------- 6. the two-phase project brief ---------- */
  function renderProj(){ const el=$("#proj"); el.innerHTML=`<p>Our biomechanics lab is working with a <b>pediatric head and neck surgery program</b> in Central Florida (a cranio-oncology service that reconstructs children's jaws after tumour surgery) on measuring how a child's jaw moves and works after mandible reconstruction. The practice already plans surgery on CT with CAD/CAM, prints patient-specific guides and implants, and uses optical navigation in the operating room; what nobody measures yet is <i>function</i> afterwards — opening, excursion, muscle use, bite force — and how it changes as the child grows. That gap is the project.</p>
      <div class="two"><div>
      <h4>The tools on the table</h4><table class="mini txt"><tr><th>System</th><th>What it does</th><th>Jaw?</th></tr>
      <tr><td><b>Theia3D</b> (markerless, in the rehab center in the same building)</td><td>Full-body pose from synchronized video, no markers — ideal for children walking</td><td>No — the head is one segment, no mandible. Covers the <b>fibula donor leg</b> (gait).</td></tr>
      <tr><td><b>Chairside jaw tracker</b> (e.g. MODJAW)</td><td>Records mandibular motion and the hinge axis, overlays it on the patient's CT/CBCT and intraoral scan</td><td>Motion only — no force, no EMG; add a bite-force sensor and surface EMG for loads.</td></tr>
      <tr><td><b>Optical marker capture</b> (Vicon, Qualisys, OptiTrack…)</td><td>Tracks reflective markers at hundreds of Hz with analogue sync for EMG and force</td><td>Yes, with custom hardware: a tooth-borne <b>dental clutch</b> carrying markers and a rigid <b>head frame</b>; the jaw model is built in software.</td></tr>
      <tr><td><b>EMG + bite force</b> (e.g. Trigno Mini sensors, a bite transducer)</td><td>Muscle activity of masseter/temporalis and the load the jaw produces</td><td>Needed for joint-load estimates; synchronize with the motion.</td></tr></table>
      <p class="note">Our portable biomechanics lab has 8 Vero v2.2 cameras, 4 mm markers, Trigno Mini EMG with a trigger module, Nexus and OpenSim — enough to build and validate the jaw model and run a pilot at the clinic.</p></div>
      <div><h4>The phased plan</h4><table class="mini txt"><tr><th>Phase</th><th>What happens</th><th>Scans</th></tr>
      <tr><td><b>0A</b> — now, no new capital</td><td>Theia gait for fibula-donor legs at the rehab center; design and print a child-sized dental clutch and head frame; file the IRB protocol (assent for children, a dentist for mixed dentition)</td><td>None new — confirm which scans the team routinely takes and whether de-identified copies can be shared</td></tr>
      <tr><td><b>0B</b> — if the portable lab is available</td><td>Build the Vicon jaw model (skull segment from the head frame, jaw segment from the clutch, labelling template, pipeline that outputs jaw motion relative to the skull); validate on adult volunteers; small pediatric pilot at the clinic with the portable cameras and EMG</td><td>CT/CBCT to register the clutch to the bone</td></tr>
      <tr><td><b>1</b> — in clinic</td><td>Chairside jaw tracker plus mini EMG and a bite-force sensor: 15-minute sessions in routine visits at 3, 6 and 12 months, then yearly</td><td>CT or CBCT plus an intraoral scan (tracker overlays motion on the child's own bone and teeth)</td></tr>
      <tr><td><b>2</b> — grant-funded</td><td>Installed optical capture with analogue sync; musculoskeletal (OpenSim) and finite-element models of the reconstructed jaw, plates and screws; the Phase 0B model and pipeline carry over</td><td>CT/CBCT for bone and hardware geometry; MRI optional, for the disc and muscle shapes</td></tr></table>
      <p class="note">Why phased: pediatric head and neck tumours are rare, so numbers are small and a grant (an NIDCR R21-type exploratory award is the classic route) is far stronger with pilot data. Go/no-go gates sit between phases.</p></div></div>
      <h4 style="margin-top:12px">What a student team owns</h4><table class="mini txt"><tr><th>Work package</th><th>Skills from this course</th></tr>
      <tr><td>Dental clutch and head frame design; registration of markers to the CT</td><td>Global vs local frames (ISB), rigid-body pose, helical axis — Frames &amp; Joints Lab and this lab</td></tr><tr><td>Jaw model in Nexus/OpenSim; filtering; soft-tissue artifact; validation on adults</td><td>Sampling and filtering — Inverse Dynamics Lab; tracking tab here</td></tr><tr><td>Joint and plate loads from bite force and EMG</td><td>Free-body diagrams, moment equilibrium — Joint Kinetics Lab; PCSA and Hill model — Muscle and MTC Labs</td></tr><tr><td>Plate, screw and implant strength, fatigue and wear</td><td>This lab and strength of materials</td></tr><tr><td>Donor-leg gait with Theia; ankle function</td><td>Gait analysis — Capstone; Theia's markerless output vs marker data</td></tr><tr><td>Growth as an outcome</td><td>Condylar growth site, bone healing — Tissue Lab; serial measurements</td></tr></table>
      <h4 style="margin-top:12px">Ground rules for a clinical partnership</h4><p>Patient imaging and motion data are protected health information: work only with de-identified data under the IRB protocol, a reliance agreement between the institutions and a data-use agreement; keep raw data on approved storage; never put a patient's images in a report or presentation without the surgeon's sign-off. Equipment brought into the hospital goes through clinical engineering, IT and infection control, and students need credentialing to work in a pediatric clinic. Engineers provide measurements and designs; the surgeon makes the clinical decisions. Document every assumption (bite force, material properties, growth) so a clinician can challenge it.</p>`; fixSubs(el); }

  /* ---------- drills ---------- */
  const DR=(()=>{ const KEY="dpl-biomech-tmj"; let St={done:0,correct:0,streak:0,best:0}; try{ Object.assign(St,JSON.parse(localStorage.getItem(KEY))||{}); }catch(e){} const save=()=>{ try{ localStorage.setItem(KEY,JSON.stringify(St)); }catch(e){} };
    const pick=(a)=>a[Math.floor(Math.random()*a.length)]; const shuffle=(a)=>a.map(x=>[Math.random(),x]).sort((p,q)=>p[0]-q[0]).map(p=>p[1]);
    const Q=[
      ()=>({q:"The TMJ is described as ginglymoarthrodial because it…",opts:shuffle(["both hinges (rotates) and glides (translates)","only rotates","only glides","is a ball-and-socket joint"]),ans:"both hinges (rotates) and glides (translates)",why:"Ginglymus = hinge, arthrodia = gliding; the disc separates the two joint spaces."}),
      ()=>({q:"During the first ≈ 20–25 mm of mouth opening the condyle mainly…",opts:shuffle(["rotates in the glenoid fossa","slides forward down the eminence","moves backward","moves laterally"]),ans:"rotates in the glenoid fossa",why:"Rotation (hinge) phase first; translation takes over for wider opening."}),
      ()=>({q:"Wide opening (beyond ≈ 25 mm) requires the condyle–disc complex to…",opts:shuffle(["translate anteriorly and inferiorly along the articular eminence","translate posteriorly","stop moving","rotate about the incisors"]),ans:"translate anteriorly and inferiorly along the articular eminence",why:"The condylar center travels about 18 mm forward and 4 mm down at full opening, with rotation continuing."}),
      ()=>({q:"A normal adult maximal interincisal opening is about…",opts:shuffle(["40–55 mm","15–20 mm","70–80 mm","5–10 mm"]),ans:"40–55 mm",why:"Less than 40 mm is considered restricted in an adult."}),
      ()=>({q:"Which imaging modality shows the TMJ disc best?",opts:shuffle(["MRI","CT","plain radiograph","optical motion capture"]),ans:"MRI",why:"MRI images soft tissue; CT/CBCT is for bone."}),
      ()=>({q:"Why is repeated CT a particular concern in a pediatric jaw study?",opts:shuffle(["ionising radiation dose accumulates in a growing child","CT cannot image bone","CT scanners are too small","children have no condyles"]),ans:"ionising radiation dose accumulates in a growing child",why:"CBCT lowers the dose; MRI and marker tracking use none."}),
      ()=>({q:"To track the mandible as a rigid body in 3-D you need at least…",opts:shuffle(["three non-collinear markers fixed to the bone (or a splint)","one marker","two markers","markers on the skin only"]),ans:"three non-collinear markers fixed to the bone (or a splint)",why:"Six degrees of freedom need three non-collinear points; skin markers slide relative to the bone."}),
      ()=>({q:"A marker that slides with the skin rather than the bone will…",opts:shuffle(["bias the rigid-body fit (soft-tissue artifact)","average out like random noise","improve the fit","have no effect"]),ans:"bias the rigid-body fit (soft-tissue artifact)",why:"Noise averages over markers; a systematic marker displacement does not."}),
      ()=>({q:"The mandible during biting acts as which class of lever?",opts:shuffle(["class III — effort between the fulcrum (TMJ) and the load (bite)","class I — fulcrum between effort and load","class II — load between fulcrum and effort","it is not a lever"]),ans:"class III — effort between the fulcrum (TMJ) and the load (bite)",why:"Muscles insert closer to the joint than the teeth, so bite force is smaller than muscle force."}),
      ()=>({q:"Moving the bite point from the molars to the incisors (same muscle effort)…",opts:shuffle(["lowers the bite force and raises the joint load","raises the bite force","does not change the joint load","unloads the muscles"]),ans:"lowers the bite force and raises the joint load",why:"Longer load arm → smaller bite force; the joint carries the difference."}),
      ()=>({q:"A typical maximal molar bite force in a healthy adult is on the order of…",opts:shuffle(["several hundred newtons (≈ 300–800 N)","10–20 N","5 000 N","1 N"]),ans:"several hundred newtons (≈ 300–800 N)",why:"Children aged 6–12 produce roughly 150–400 N."}),
      ()=>({q:"The bearing surface of the fossa component of a TMJ total joint replacement is usually…",opts:shuffle(["UHMWPE (polyethylene) on a metal backing","solid cobalt–chromium","bone cement","silicone"]),ans:"UHMWPE (polyethylene) on a metal backing",why:"Metal (CoCr) on polyethylene, as in hip and knee replacements."}),
      ()=>({q:"After a total TMJ replacement, maximal opening is usually…",opts:shuffle(["smaller than normal because the translation phase is largely lost","larger than normal","unchanged","zero"]),ans:"smaller than normal because the translation phase is largely lost",why:"The device is a hinge; lateral pterygoid-driven translation is lost."}),
      ()=>({q:"The main reason alloplastic TMJ replacements are avoided in young children is that…",opts:shuffle(["the implant cannot grow with the mandible (condylar growth site)","children cannot chew","the materials are toxic to children","children have no TMJ"]),ans:"the implant cannot grow with the mandible (condylar growth site)",why:"Growing reconstructions (costochondral graft, distraction osteogenesis) are preferred; TJR for selected cases with planned revision."}),
      ()=>({q:"A costochondral graft is used to rebuild a child's condyle because…",opts:shuffle(["its cartilage cap can keep growing","it is made of metal","it never needs revision","it has no donor site"]),ans:"its cartilage cap can keep growing",why:"Growth is unpredictable (too little or too much), which is its main drawback."}),
      ()=>({q:"Distraction osteogenesis lengthens the mandible by…",opts:shuffle(["slowly separating a surgical cut (~1 mm/day) while new bone forms in the gap","inserting a metal joint","removing bone","wearing a brace"]),ans:"slowly separating a surgical cut (~1 mm/day) while new bone forms in the gap",why:"Used for mandibular hypoplasia such as hemifacial microsomia."}),
      ()=>({q:"Archard's wear law V = k·F·s says polyethylene wear volume grows with…",opts:shuffle(["load and sliding distance","time only","temperature only","the elastic modulus"]),ans:"load and sliding distance",why:"The TMJ is helped by small sliding distances and modest loads."}),
      ()=>({q:"For a condylar stem loaded a million times a year the governing material property is the…",opts:shuffle(["fatigue (endurance) strength","ultimate tensile strength only","hardness","density"]),ans:"fatigue (endurance) strength",why:"Cyclic loading well below yield can still crack a stem at a notch."}),
      ()=>{ const Fm=pick([300,400,500]), a=30, b=pick([45,60,90]); const Fb=Fm*a/b; return {q:`Vertical muscle force ${Fm} N acts ${a} mm anterior of the condyle; the bite point is ${b} mm anterior. Bite force?`,opts:shuffle([`${Fb.toFixed(0)} N`,`${(Fm*b/a).toFixed(0)} N`,`${Fm} N`,`${(Fm-Fb).toFixed(0)} N`]),ans:`${Fb.toFixed(0)} N`,why:`Moments about the condyle: F_b = F_m·a/b = ${Fm}·${a}/${b} = ${Fb.toFixed(0)} N; the joint carries F_m − F_b = ${(Fm-Fb).toFixed(0)} N.`}; },
      ()=>{ const r=90, o=pick([10,15,20]); const th=o/r*180/Math.PI; return {q:`Rotation-only opening of ${o} mm at the incisors, ${r} mm from the condyle: rotation angle?`,opts:shuffle([`${th.toFixed(1)}°`,`${(th*2).toFixed(1)}°`,`${(o).toFixed(1)}°`,`${(th/2).toFixed(1)}°`]),ans:`${th.toFixed(1)}°`,why:`θ ≈ s/r = ${o}/${r} = ${(o/r).toFixed(3)} rad = ${th.toFixed(1)}°.`}; },
      ()=>({q:"Why can a markerless full-body system such as Theia3D not track the jaw?",opts:shuffle(["its body model treats the head as one segment with no mandible","it has too many cameras","it only works outdoors","it cannot see children"]),ans:"its body model treats the head as one segment with no mandible",why:"It still covers the fibula-donor leg (gait) at no extra cost; the jaw needs its own tools."}),
      ()=>({q:"To track the mandible with an optical marker system you attach markers to…",opts:shuffle(["a tooth-borne dental clutch, with a rigid head frame to subtract head motion","the lips","the chin skin","the ears"]),ans:"a tooth-borne dental clutch, with a rigid head frame to subtract head motion",why:"Skin markers slide several millimeters over the jaw; the clutch moves with the teeth and bone."}),
      ()=>({q:"A chairside jaw tracker records motion and the hinge axis but not…",opts:shuffle(["muscle activity or bite force — add EMG and a bite sensor","opening distance","lateral excursion","the condylar path"]),ans:"muscle activity or bite force — add EMG and a bite sensor",why:"Loads on the joint, plates and screws need force and EMG, synchronized with the motion."}),
      ()=>({q:"The bone used to rebuild a child's mandible after tumour resection usually comes from the…",opts:shuffle(["fibula (free flap with its blood vessels)","skull","rib only","pelvis only"]),ans:"fibula (free flap with its blood vessels)",why:"Hence two surgical sites — jaw and leg — and two sets of outcomes to measure."}),
      ()=>({q:"Which phase of the plan needs no new scans at all?",opts:shuffle(["Phase 0 — Theia gait and clutch design","Phase 1 — chairside tracker","Phase 2 — finite-element models","every phase needs a new CT"]),ans:"Phase 0 — Theia gait and clutch design",why:"Phase 1 uses the routine CT/CBCT plus an intraoral scan; Phase 2 uses CT/CBCT for geometry with MRI optional. No phase adds radiation."}),
      ()=>({q:"Patient-specific TMJ implants are designed from…",opts:shuffle(["the patient's CT (often via a 3-D-printed skull model)","a standard size chart","an MRI of the disc only","a photograph"]),ans:"the patient's CT (often via a 3-D-printed skull model)",why:"Hence imaging and registration come first in a design project."}),
      ()=>({q:"Patient imaging and motion data in a clinical collaboration must be…",opts:shuffle(["de-identified and handled under IRB approval and a data agreement","posted to the team's shared drive","shown in the final presentation with names","emailed freely"]),ans:"de-identified and handled under IRB approval and a data agreement",why:"Protected health information; the surgeon signs off on any image used."})];
    let cur=null; function next(){ cur=pick(Q)(); const el=$("#jdrill"); el.innerHTML=`<div class="dq">${cur.q}</div><div class="dopts">${shuffle(cur.opts).map(o=>`<button type="button" class="btn dopt" data-o="${o.replace(/"/g,"&quot;")}">${o}</button>`).join("")}</div><div class="dfb" id="jdfb"></div><div class="dstat">Answered ${St.done} · correct ${St.correct} · in a row ${St.streak} (best ${St.best})</div>`; el.querySelectorAll(".dopt").forEach(b=>b.onclick=()=>answer(b.dataset.o,b)); fixSubs(el); }
    function answer(o,b){ const ok=o===cur.ans; St.done++; if(ok){ St.correct++; St.streak++; St.best=Math.max(St.best,St.streak); } else St.streak=0; save(); $("#jdrill").querySelectorAll(".dopt").forEach(x=>{ x.disabled=true; if(x.dataset.o===cur.ans) x.classList.add("good"); else if(x===b&&!ok) x.classList.add("bad"); }); $("#jdfb").innerHTML=`<p class="${ok?"fb good":"fb bad"}">${ok?"Correct.":"Not quite — the answer is <b>"+cur.ans+"</b>."} ${cur.why}</p><button type="button" class="btn primary small" id="jnext">Next question →</button>`; $("#jnext").onclick=next; const ds=$("#jdrill .dstat"); if(ds) ds.textContent=`Answered ${St.done} · correct ${St.correct} · in a row ${St.streak} (best ${St.best})`; if(typeof GAME!=="undefined"&&ok) GAME.addXP(10,St.streak>1?`+10 XP · ${St.streak} in a row`:"+10 XP"); }
    return {next}; })();

  function init(){ renderAnat(); renderTrack(); renderLever(); renderImpl(); renderStudy(); renderProj();
    document.querySelectorAll("#mtabs .tabbtn").forEach(b=>b.onclick=()=>{ document.querySelectorAll("#mtabs .tabbtn").forEach(x=>x.classList.toggle("on",x===b)); document.querySelectorAll(".mpane").forEach(p=>p.hidden=p.id!==b.dataset.k); });
    $("#jdrillstart").onclick=()=>{ DR.next(); $("#jdrillstart").textContent="Skip →"; }; }
  return {init,jawPose,lever,stem,kabsch2,JAW};
})();
